package com.keepcalm.placementportal.controller;import com.keepcalm.placementportal.service.StudentEventService;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/students/me")@RequiredArgsConstructor public class StudentEventController{private final StudentEventService service;@GetMapping("/events")public List<Map<String,Object>> events(){return service.events();}@GetMapping("/calendar")public List<Map<String,Object>> calendar(){return service.calendar();}}
